INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'airbyte' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-airbyte@v0.1.3 vgi-airbyte-worker');

-- What is in the registry, and under which licenses?
SELECT name, version, license, license_policy
FROM airbyte.main.connectors() WHERE manifest_only ORDER BY name;

-- PokeAPI needs no key; its whole config is the pokemon to fetch.
CREATE SECRET poke (TYPE airbyte, SCOPE 'airbyte://source-pokeapi', CONFIG '{"pokemon_name": "pikachu"}');

-- ELv2-licensed: acknowledge the license to run it.
SELECT id, name, base_experience, height, weight
FROM airbyte.main.read_stream('source-pokeapi', 'pokemon', accept_license := 'ELv2');

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'anomaly' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-anomaly@v0.5.2 vgi-anomaly-worker');

-- Pass an ordered query directly; results are ordinary rows.
SELECT * FROM anomaly.discord_index((SELECT v FROM series ORDER BY t), window_size := 50);
SELECT * FROM anomaly.motif_index((SELECT v FROM series ORDER BY t), window_size := 50);
SELECT * FROM anomaly.matrix_profile((SELECT v FROM series ORDER BY t), window_size := 50);
SELECT * FROM anomaly.change_points((SELECT v FROM series ORDER BY t));
SELECT * FROM anomaly.change_points((SELECT v FROM series ORDER BY t), n_bkps := 2);
SELECT * FROM anomaly.zscore_anomalies((SELECT v FROM series ORDER BY t), threshold := 3.0);

-- Existing scalar calls still work, including literal arrays and GROUP BY.
SELECT anomaly.discord_index([1.0,2.0,3.0,100.0,2.0,3.0,1.0]::DOUBLE[], 3);

CREATE SECRET anthropic (TYPE anthropic_admin, api_key 'sk-ant-admin01-...');
ATTACH 'anthropic' (TYPE vgi, LOCATION 'uv run anthropic_worker.py');

-- Who is spending what, this month?
SELECT COALESCE(w.name, 'Default') AS workspace, c.model, sum(c.amount_usd) AS usd
FROM anthropic.cost_report(date_trunc('month', current_date)) c
LEFT JOIN anthropic.workspaces w ON w.id = c.workspace_id
GROUP BY ALL ORDER BY usd DESC;

-- Which roles use Claude Code, and what does it cost? (8 days, today included)
SELECT u.role, sum(c.num_sessions) AS sessions, sum(c.estimated_cost_usd) AS usd
FROM anthropic.claude_code_usage(current_date - INTERVAL 7 DAY, ending_date => current_date) c
JOIN anthropic.users u ON u.email = c.email_address
GROUP BY u.role ORDER BY sessions DESC;

LOAD vgi;
ATTACH 'asn1' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-asn1@v0.4.2');
SET search_path = 'asn1.main';

-- Decode any BER/DER blob to JSON, to self-describing JSON, and to a dump.
SELECT decode(from_hex('3003020105'));                 -- '[5]'
SELECT to_json(payload), dump(payload) FROM read_blob('s3://pki/*.der');

-- Resolve OIDs and inventory every OID in a blob.
SELECT oid_name('1.2.840.113549.1.1.11');              -- 'sha256WithRSAEncryption'
SELECT oids(data) FROM blobs;                          -- LIST<STRUCT(oid,name,path)>

-- Robust, verify-free triage: well-formedness with a classified failure kind.
SELECT well_formed(data) FROM unknown_blobs WHERE NOT (well_formed(data)).ok;

-- Shred a CMS SignedData (a literal blob) into one row per signer; the
-- signer_cert_sha256 column joins embedded signer certs to vgi-x509.
SELECT s.digest_alg, s.sig_alg, s.signing_time, s.signer_cert_sha256
FROM cms_signers(from_hex('304d0201013100301106092a864886f70d010701a00404026869a0053003020105312c302a020101800401020304300b0609608648016503040201300d06092a864886f70d01010105000403aabbcc')) s;

-- Compose: split a PEM bundle, then triage each block's DER with the scalars.
SELECT p.idx, p.label, (well_formed(p.der)).ok AS ok, len(oids(p.der)) AS n_oids
FROM pem_decode('-----BEGIN PRIVATE KEY-----' || chr(10) || 'MBYCAQAwDQYJKoZIhvcNAQEBBQAEAmhp'
                || chr(10) || '-----END PRIVATE KEY-----') p
ORDER BY p.idx;                                        -- 0, PRIVATE KEY, true, 1

