ATTACH 'cloudquery' AS cq (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-cloudquery@v0.1.3',
    plugins 'github:cloudquery/test@v4.1.0, crowdstrike=github:justmiles/crowdstrike@v2.1.0',
    spec    '{"test": {"num_rows": 3}}');

SELECT p.resource_id, count(*) AS subs
FROM cq.test.test_some_table p JOIN cq.test.test_sub_table s ON s._cq_parent_id = p._cq_id
GROUP BY ALL;

example_queries.sql:
SELECT code.main.loc('fn a() {}
// note
fn b() {}
', 'rust')

SELECT name, start_line, end_line FROM code.main.symbols('fn a() {}
fn b() {}
', 'rust') WHERE kind = 'function' ORDER BY start_line

SELECT f.path, code.main.language_of(f.path) AS lang, code.main.loc(f.src, code.main.language_of(f.path)) AS code_lines, code.main.count_functions(f.src, code.main.language_of(f.path)) AS functions, len(code.main.extract_imports(f.src, code.main.language_of(f.path))) AS imports FROM (VALUES ('src/lib.rs', 'use std::fmt;
// helper
fn a() {}
fn b() {}
'), ('app/main.py', 'import os

def run():
    pass
')) AS f(path, src) ORDER BY f.path

SELECT s.name AS caller, c.text AS callee, c.start_line FROM code.main.symbols('fn main() {
    parse();
    run();
}
fn run() {
    log();
}
', 'rust') AS s JOIN code.main.ts_nodes('fn main() {
    parse();
    run();
}
fn run() {
    log();
}
