INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'compress' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-compress@v0.4.3');
SET search_path = 'compress.main';

-- 1. Decompress a column of gzip'd HTTP bodies in a log table.
SELECT request_id,
       decompress(body_gz, 'gzip')::VARCHAR AS body   -- BLOB -> BLOB, cast to text
FROM http_logs
WHERE detect_codec(body_gz) = 'gzip';

-- 2. Recompress a cold archive gzip -> zstd (transcode in place, no files).
UPDATE archive
SET payload = compress(decompress(payload, 'gzip'), 'zstd', 19),
    codec   = 'zstd';

-- 3. Auto-detect + decompress a mixed-codec Kafka payload column, with a bomb guard.
SELECT topic, partition, "offset",
       detect_codec(value)                 AS codec,
       decompress_auto(value, 67108864)    AS plaintext   -- cap 64 MiB/row
FROM kafka_messages;

-- 4. Compress a query result for export, and report the win.
SELECT compressed_size(blob, 'zstd', 19)   AS bytes_out,
       ratio(blob, 'zstd', 19)             AS ratio,   -- out/in, < 1.0 means it shrank
       compress(blob, 'zstd', 19)          AS packed
FROM (SELECT string_agg(line, '\n')::BLOB AS blob FROM report_lines);

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'cricket' (
  TYPE vgi,
  LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-cricket@v0.2.2 vgi-cricket'
);

INSTALL vgi FROM community; LOAD vgi;

ATTACH 'cve' AS cve (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-cve@v0.5.2');

-- Offline CVSS math (no network):
SELECT cve.cvss_base_score('CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H'); -- 9.8
SELECT cve.cvss_severity(9.8);                                              -- CRITICAL

-- Look up a CVE from the NVD API:
SELECT id, cvss_score, cvss_severity, cwe FROM cve.cve('CVE-2021-44228');

-- Keyword search (paginated, bounded to 100 results):
SELECT id, cvss_severity, published FROM cve.cve_search('log4j');

-- CVEs affecting a CPE name:
SELECT cve_id, cvss_score, cvss_severity
FROM cve.cpe_cves('cpe:2.3:a:apache:log4j:2.14.1:*:*:*:*:*:*:*');

-- Is it actively exploited (CISA KEV)? How likely is exploitation (EPSS)?
SELECT cve_id, date_added, known_ransomware_campaign_use FROM cve.kev_cve('CVE-2021-44228');
SELECT cve_id, epss, percentile FROM cve.epss(['CVE-2021-44228', 'CVE-2022-22965']);

-- Advisories affecting an open-source package version (OSV.dev):
SELECT id, cve_ids, fixed_versions FROM cve.osv_query('PyPI', 'jinja2', version := '2.4.1');

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'datahub' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-datahub@v0.1.3 vgi-datahub-worker');

CREATE SECRET datahub (TYPE datahub, GMS_URL 'http://localhost:8080', TOKEN '<personal access token>');

-- Snowflake tables nobody owns.
SELECT qualified_name FROM datahub.main.datasets
WHERE platform = 'snowflake' AND len(owners) = 0 ORDER BY qualified_name;

-- Columns tagged PII.
SELECT qualified_name, column_name FROM datahub.main.columns WHERE list_contains(tags, 'pii');

-- What breaks if this raw table changes?
SELECT entity_type, name, degree
FROM datahub.main.lineage(datahub.main.dataset_urn('snowflake', 'analytics.raw.orders'),
                          direction := 'downstream', max_hops := 5)
ORDER BY degree;

-- Failing quality checks.
SELECT qualified_name, assertion_type, description, last_run_at
FROM datahub.main.assertions WHERE last_status = 'failed';

INSTALL vgi FROM community;     -- Haybarn 2.0; on DuckDB 2.0 use the query_farm repository
LOAD vgi;
ATTACH 'dbt' (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-dbt@v0.1.3');

INSTALL vgi FROM community;
LOAD vgi;

ATTACH 'disasm' AS disasm (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-disasm@v0.4.1');

-- Disassemble an x64 shellcode blob and project the instruction address, mnemonic, and
-- operands.
SELECT address, mnemonic, op_str FROM disasm.main.disassemble(from_hex('554889e5c3'), arch := 'x86', mode := 'x64');

-- Probe a blob by its magic bytes and read back just the detected container format.
SELECT (disasm.main.format(from_hex('7f454c46'))).container AS container;

INSTALL vgi FROM community;   -- Haybarn 2.0; on DuckDB 2.0 use the query_farm repository (below)
LOAD vgi;
ATTACH 'dlt' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-dlt@v0.1.2 vgi-dlt-worker');

-- A REST API described with dlt's rest_api config.
SET VARIABLE gh = '{
  "client": {"base_url": "https://api.github.com/repos/dlt-hub/dlt/"},
  "resource_defaults": {"endpoint": {"params": {"per_page": 100}}},
  "resources": [
    {"name": "issues", "primary_key": "id",
     "endpoint": {"path": "issues", "params": {"state": "all",
       "since": {"type": "incremental", "cursor_path": "updated_at", "initial_value": "2026-01-01T00:00:00Z"}}}}
  ]}';

-- The token never appears in the query: it is merged into the config from a secret.
CREATE SECRET github (TYPE dlt, SCOPE 'dlt://rest_api/api.github.com',
    CONFIG '{"client": {"auth": {"type": "bearer", "token": "ghp_..."}}}');

SELECT name, primary_key, incremental_cursor FROM dlt.main.resources('rest_api', config := getvariable('gh'));

SELECT user.login, count(*) AS issues
FROM dlt.main.read_resource('rest_api', 'issues', config := getvariable('gh'))
WHERE updated_at >= TIMESTAMPTZ '2026-06-01'      -- sent to GitHub as ?since=2026-06-01T00:00:00Z
GROUP BY ALL ORDER BY issues DESC;

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'docgen' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-docgen@v0.4.3 vgi-docgen');

-- One rendered DOCX per row (scalar): template + a STRUCT of row data -> BLOB
SELECT docgen.docgen_render('invoice.docx', {customer: name, total: amount})
FROM invoices;

-- Inline template bytes work too (BLOB template instead of a path)
SELECT docgen.docgen_render(tpl.bytes, {customer: name})
FROM letters, templates AS tpl;

-- Opt into PDF (3rd positional arg; requires headless LibreOffice on PATH)
SELECT docgen.docgen_render('invoice.docx', {total: amount}, true) FROM invoices;

-- Many rows -> ONE merged document (buffering): template as a NAMED arg
SELECT doc FROM docgen.docgen_merge(
    (SELECT customer, total FROM invoices),
    template := 'invoice.docx');

