-- the readers take a local path ('/data/book.xlsx') or the workbook bytes; here,
-- a two-sheet sample workbook from this repo, fetched once into a variable
SET VARIABLE book = (SELECT content
  FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-poi/v0.4.0/test/sql/data/sample.xlsx'));

-- every non-blank cell of a workbook, with type + evaluated formula value
SELECT sheet, cell_ref, value, type, formula
FROM excel.read_excel(getvariable('book'));

-- the worksheet directory: Numbers (2x3) and Other (1x1)
SELECT * FROM excel.excel_sheets(getvariable('book'));

-- combine them: each sheet's used range next to its cell and formula counts
SELECT s.name, s.rows, s.cols, count(c.cell_ref) AS cells, count(c.formula) AS formulas
FROM excel.excel_sheets(getvariable('book')) AS s
LEFT JOIN excel.read_excel(getvariable('book')) AS c ON c.sheet = s.name
GROUP BY ALL ORDER BY s.name;

