INSTALL vgi FROM community; LOAD vgi;
ATTACH 'recommender' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-recommender@v0.4.1 vgi-recommender');

-- Top-10 recommended items per user (already-seen items excluded)
SELECT * FROM recommender.recommend_all((SELECT u, i, v FROM events),
                                        user := 'u', item := 'i', value := 'v', n := 10)
ORDER BY user, rank;

-- Top-5 most similar items per item (cosine of ALS item factors)
SELECT * FROM recommender.similar_items((SELECT u, i, v FROM events),
                                        user := 'u', item := 'i', value := 'v', n := 5)
ORDER BY item, rank;

-- Top-5 recommendations for ONE user
SELECT * FROM recommender.recommend_for((SELECT u, i, v FROM events),
                                        user := 'u', item := 'i', value := 'v',
                                        target_user := 'alice', n := 5)
ORDER BY rank;

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'rerank' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-rerank@v0.4.1 vgi-rerank-worker');

-- Score one query/document pair (higher = more relevant).
SELECT rerank.rerank_score('how do I reset my password',
                           'Click the forgot password link to reset it.');

-- THE pattern: rerank a top-K candidate set (e.g. from VSS / BM25) by relevance.
SELECT id, chunk
FROM candidates                       -- the ~100 rows recall handed you
ORDER BY rerank.rerank_score('how do I reset my password', chunk) DESC
LIMIT 10;

-- What models are available?
SELECT * FROM rerank.supported_models();

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'rugby' (
  TYPE vgi,
  LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-rugby@v0.2.2 vgi-rugby'
);

ATTACH 'salesforce' (TYPE vgi, LOCATION '/abs/path/to/vgi-salesforce/bin/vgi-salesforce-worker');

SELECT e.opportunity_id,
       salesforce.main.id18(e.opportunity_id)      AS join_key,     -- 15 → 18, and repairs Excel-mangled case
       salesforce.main.object_of(e.opportunity_id) AS sobject       -- '006…' → 'Opportunity'
FROM read_csv('~/Downloads/report1234567.csv') e
WHERE salesforce.main.is_valid_id(e.opportunity_id);

