LOAD vgi;

ATTACH 'saml' AS saml (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-saml@v0.4.2');

-- Identify a SAML message by its root element.
SELECT saml.main.message_type('<samlp:Response xmlns:samlp="urn:oasis:names:tc:SAML:2.0:protocol"/>') AS kind;

-- Triage why a blob is not a usable SAML message.
SELECT (saml.main.well_formed('not a saml message')).kind AS kind;

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'scholar' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-scholar@v0.4.1 vgi-scholar-worker');

-- top-N results from OpenAlex (the default provider)
SELECT title, authors, year, doi, citations_count
FROM scholar.scholar_search('retrieval augmented generation', count := 10);

-- search Crossref or arXiv instead
SELECT title, doi FROM scholar.scholar_search('graph neural networks', provider := 'crossref', count := 5);
SELECT title, url FROM scholar.scholar_search('diffusion models',    provider := 'arxiv',    count := 5);

-- which providers are available?
SELECT * FROM scholar.scholar_providers();

INSTALL vgi FROM community; LOAD vgi;

-- Attach with zero local install — from the GitHub release via uvx, or from ghcr via oci://
ATTACH 'skbio' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-scikit-bio@v0.3.1 vgi-scikit-bio');
-- ATTACH 'skbio' (TYPE vgi, LOCATION 'oci://ghcr.io/query-farm/vgi-scikit-bio:0.3.1');

SELECT skbio.sequence.gc_content('ATGCGGATTACAGG');            -- 0.5
SELECT skbio.sequence.reverse_complement('ATGCGGATTACAGG');    -- CCTGTAATCCGCAT
SELECT skbio.sequence.translate('ATGCGGATTACAGGT');            -- MRITG

-- one-time: load the extension and attach the worker
INSTALL vgi FROM community; LOAD vgi;
ATTACH 'sklearn' (TYPE vgi, LOCATION 'vgi-sklearn');   -- 'uv run sklearn_worker.py' from a checkout

-- train a model on a table and score rows, all in SQL
CREATE TABLE flowers AS SELECT * FROM sklearn.datasets.iris();

CREATE TABLE model AS
  SELECT model FROM sklearn.estimators.fit_random_forest_classifier(
    (SELECT sepal_length_cm, sepal_width_cm, petal_length_cm, petal_width_cm, target FROM flowers),
    target := 'target', n_estimators := 200);

SET VARIABLE m = (SELECT model FROM model);
SELECT sample_id, prediction
FROM sklearn.models.predict((SELECT * EXCLUDE (target) FROM flowers), model := getvariable('m'), id := 'sample_id')
LIMIT 5;

INSTALL vgi FROM community; LOAD vgi;
ATTACH 'search' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-search@v0.4.2 vgi-search-worker');

-- Top-N web search via the configured/default provider.
SELECT title, url, snippet, rank, source, published
FROM search.web_search('duckdb arrow protocol', provider := 'brave', count := 10);

-- RAG composition: search the web, then rank by your own embedding similarity.
WITH hits AS (SELECT * FROM search.web_search('vector databases', provider := 'tavily', count := 20))
SELECT url, snippet FROM hits;  -- ... ORDER BY rerank_score(:q, snippet) DESC LIMIT 5;

-- A free, no-key quick fact (DuckDuckGo Instant Answer — zero-click box).
SELECT search.web_answer('python programming language', 'ddg');

-- Compose both: the instant answer plus the top-5 result URLs to cite with it.
SELECT search.web_answer('python programming language', 'ddg') AS answer,
       list(url ORDER BY rank) AS sources
FROM search.web_search('python programming language', provider := 'ddg', count := 5);

-- Which providers are available and configured?
SELECT * FROM search.search_providers() ORDER BY provider;

INSTALL vgi FROM community; LOAD vgi;

ATTACH 'secretscan' AS secretscan (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-secretscan@v0.4.1');

-- Cheap predicate: does this text contain any secret? (great in a WHERE clause)
SELECT secretscan.secret_contains('deploy AKIAZ3MZ7EXAMPLE4Q2T now');  -- true

-- Find every secret, one row per finding (redacted match only).
SELECT rule_id, match_redacted, start_offset, entropy, confidence
FROM secretscan.secret_scan('SLACK_TOKEN=xoxb-1234567890-1234567890123-AbCdEfGhIjKlMnOpQrStUvWx');
-- slack-bot-token | xoxb********UvWx | 12 | 5.02 | 0.95

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'singer' (TYPE vgi, LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-singer@v0.1.1 vgi-singer-worker');

-- The tap's config: exactly what the tap reads from --config.
CREATE SECRET csv (TYPE singer, SCOPE 'singer://tap-csv', CONFIG '{
  "files": [{"entity": "customers", "path": "/data/customers.csv", "keys": ["id"]}]}');

-- What does the tap offer?
SELECT stream, key_properties, columns
FROM singer.main.discover('tap-csv', pip_url := 'git+https://github.com/MeltanoLabs/tap-csv.git@v1.3.2');

-- Read a stream.
SELECT * FROM singer.main.read_stream('tap-csv', 'customers',
    pip_url := 'git+https://github.com/MeltanoLabs/tap-csv.git@v1.3.2');

SET allow_extension_repositories = 'allowed';
CREATE EXTENSION REPOSITORY IF NOT EXISTS query_farm WITH PREFIX 'https://duckdb-extensions.query.farm';
INSTALL vgi FROM query_farm;
LOAD vgi FROM query_farm;

ATTACH 'slack' (TYPE vgi, LOCATION '/abs/path/to/vgi-slack/bin/vgi-slack-worker',
                token getenv('SLACK_BOT_TOKEN'));

SELECT team, user FROM slack.main.auth_info();

-- Interface traffic, one row per interface, Counter64 as UBIGINT.
SELECT ifName, ifHCInOctets, ifHCOutOctets
FROM snmp.main.snmp_table('10.0.0.1', 'ifXTable')
ORDER BY ifHCInOctets DESC;

-- Disk and memory use from HOST-RESOURCES-MIB.
SELECT hrStorageDescr, round(100.0 * hrStorageUsed / nullif(hrStorageSize, 0), 1) AS pct_used
FROM snmp.main.snmp_table('10.0.0.1', 'hrStorageTable');

-- Specific instances.
SELECT object, value FROM snmp.main.snmp_get('10.0.0.1', 'sysName.0', 'sysDescr.0', 'sysUpTime.0');

INSTALL vgi FROM community;
LOAD vgi;
ATTACH 'soccer' (
  TYPE vgi,
  LOCATION 'uvx --from git+https://github.com/Query-farm/vgi-soccer@v0.2.2 vgi-soccer'
);

INSTALL vgi FROM community;
LOAD vgi;

ATTACH 'sourcemap' AS sourcemap (TYPE vgi, LOCATION 'github-auto://Query-farm/vgi-sourcemap@v0.4.2');

-- Decode a source map into its full token (mapping) table.
SELECT gen_line, gen_col, source FROM sourcemap.main.tokens('{"version":3,"file":"o.js","sources":["index.js"],"names":[],"mappings":"AAAA"}');

-- Resolve a minified (line, col) position to its original source location.
SELECT sourcemap.main.lookup('{"version":3,"file":"o.js","sources":["index.js"],"names":[],"mappings":"AAAA"}', 0, 0);

