-- (ImageNet class indexes 151-268), looked up in the class list.
SELECT p.id, c.label AS breed
FROM photos AS p
JOIN vision.image_classes AS c ON c.label = vision.top_label(p.image)
WHERE c.idx BETWEEN 151 AND 268
ORDER BY p.id;

